package cdc

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strconv"
)

var ErrTargetOwnershipConflict = errors.New("目标 Schema 已被其他增量任务占用")
var ErrCheckpointMissing = errors.New("缺少目标检查点，请从经核验的基线重新建立任务")

// This key cannot be generated by the API, whose task identifiers are UUIDs.
const schemaOwnerKey = "__dbgold_cdc_schema_owner__"

type checkpointExecutor interface {
	ExecContext(context.Context, string, ...any) (sql.Result, error)
}

type checkpointQueryer interface {
	QueryRowContext(context.Context, string, ...any) *sql.Row
}

type checkpointStore struct {
	db           *sql.DB
	table, jobID string
	postgres     bool
}

func checkpointStoreFor(a targetApplier) checkpointStore {
	switch a := a.(type) {
	case *PostgresApplier:
		return checkpointStore{a.db, a.checkpointTable(), a.jobID, true}
	case *DamengApplier:
		return checkpointStore{a.db, a.checkpointTable(), a.jobID, false}
	default:
		panic("CDC target has no checkpoint store")
	}
}

func (s checkpointStore) bind(index int) string {
	if s.postgres {
		return "$" + strconv.Itoa(index)
	}
	return "?"
}

func (s checkpointStore) owner(ctx context.Context, q checkpointQueryer, lock bool) (string, error) {
	statement := "SELECT binlog_file FROM " + s.table + " WHERE job_id=" + s.bind(1) + " AND bootstrap_state='schema_owner'"
	if lock {
		statement += " FOR UPDATE"
	}
	var owner string
	err := q.QueryRowContext(ctx, statement, schemaOwnerKey).Scan(&owner)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	return owner, err
}

func (s checkpointStore) requireOwner(ctx context.Context, q checkpointQueryer, lock bool) error {
	owner, err := s.owner(ctx, q, lock)
	if err != nil {
		return fmt.Errorf("读取目标 Schema 占用失败: %w", err)
	}
	if owner != s.jobID {
		return fmt.Errorf("%w，当前任务没有有效的目标占用", ErrTargetOwnershipConflict)
	}
	return nil
}

func newExistingTargetApplier(ctx context.Context, cfg Config) (targetApplier, error) {
	cfg.RequireExistingCheckpoint = true
	return newTargetApplier(ctx, cfg)
}

// ClaimTargetSchema keeps ownership in the physical schema, so two aliases
// or credentials addressing the same schema participate in the same lock.
func ClaimTargetSchema(ctx context.Context, cfg Config, legacyJobs []string, terminal func(string) (bool, error)) error {
	applier, err := newTargetApplier(ctx, cfg)
	if err != nil {
		return err
	}
	defer applier.Close()
	s := checkpointStoreFor(applier)
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	owner, err := s.owner(ctx, tx, true)
	if err != nil {
		return err
	}
	if owner == s.jobID {
		return nil
	}
	if owner != "" {
		canReplace, err := terminal(owner)
		if err != nil {
			return err
		}
		if !canReplace {
			return ErrTargetOwnershipConflict
		}
	}
	for _, job := range legacyJobs {
		if job == s.jobID {
			continue
		}
		var marker int
		statement := "SELECT 1 FROM " + s.table + " WHERE job_id=" + s.bind(1)
		err = tx.QueryRowContext(ctx, statement, job).Scan(&marker)
		if err == nil {
			return ErrTargetOwnershipConflict
		}
		if !errors.Is(err, sql.ErrNoRows) {
			return err
		}
	}
	if owner != "" {
		statement := "UPDATE " + s.table + " SET binlog_file=" + s.bind(1) + " WHERE job_id=" + s.bind(2)
		result, err := tx.ExecContext(ctx, statement, s.jobID, schemaOwnerKey)
		if err != nil {
			return err
		}
		if err = requireCheckpointWrite(result); err != nil {
			return err
		}
		return tx.Commit()
	}
	statement := fmt.Sprintf("INSERT INTO %s (job_id,binlog_file,bootstrap_state) VALUES (%s,%s,'schema_owner')", s.table, s.bind(1), s.bind(2))
	if _, err = tx.ExecContext(ctx, statement, schemaOwnerKey, s.jobID); err != nil {
		// A competing claim on a previously empty schema can win the unique
		// key only after we issued our lookup. Read again outside this transaction.
		_ = tx.Rollback()
		if winner, readErr := s.owner(ctx, s.db, false); readErr == nil && winner != "" {
			if winner == s.jobID {
				return nil
			}
			return ErrTargetOwnershipConflict
		}
		return err
	}
	return tx.Commit()
}

func CheckTargetSchemaOwner(ctx context.Context, cfg Config) error {
	applier, err := newExistingTargetApplier(ctx, cfg)
	if err != nil {
		return err
	}
	defer applier.Close()
	return checkTargetSchemaOwner(ctx, applier)
}

func checkTargetSchemaOwner(ctx context.Context, applier targetApplier) error {
	s := checkpointStoreFor(applier)
	return s.requireOwner(ctx, s.db, false)
}

func ReleaseTargetSchema(ctx context.Context, cfg Config) error {
	applier, err := newExistingTargetApplier(ctx, cfg)
	if err != nil {
		return err
	}
	defer applier.Close()
	s := checkpointStoreFor(applier)
	statement := fmt.Sprintf("DELETE FROM %s WHERE job_id=%s AND binlog_file=%s AND bootstrap_state='schema_owner'", s.table, s.bind(1), s.bind(2))
	_, err = s.db.ExecContext(ctx, statement, schemaOwnerKey, s.jobID)
	return err
}

func requireCheckpointWrite(result sql.Result) error {
	count, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if count != 1 {
		return fmt.Errorf("目标检查点已变化，更新影响 %d 行", count)
	}
	return nil
}

type targetCheckpointGuard struct {
	position         Position
	sourceSchemaHash string
}

func lockTargetCheckpoint(ctx context.Context, tx *sql.Tx, a targetApplier, expected targetCheckpointGuard) error {
	s := checkpointStoreFor(a)
	if err := s.requireOwner(ctx, tx, true); err != nil {
		return err
	}
	var file, gtid, schemaHash sql.NullString
	var offset uint32
	var state string
	statement := "SELECT binlog_file,binlog_position,gtid,bootstrap_state,source_schema_hash FROM " + s.table + " WHERE job_id=" + s.bind(1) + " FOR UPDATE"
	err := tx.QueryRowContext(ctx, statement, s.jobID).Scan(&file, &offset, &gtid, &state, &schemaHash)
	if errors.Is(err, sql.ErrNoRows) {
		return ErrCheckpointMissing
	}
	if err != nil {
		return err
	}
	actual := Position{File: file.String, Pos: offset, GTID: gtid.String}
	if state != "completed" || !PositionEquivalent(actual, expected.position) || schemaHash.String != expected.sourceSchemaHash {
		return fmt.Errorf("目标检查点在同步期间发生变化")
	}
	return nil
}

func applyExistingCheckpoint(ctx context.Context, a targetApplier, changes []Change, previous, next Position, schemaHash string) (Stats, error) {
	guard := targetCheckpointGuard{position: previous, sourceSchemaHash: schemaHash}
	switch a := a.(type) {
	case *PostgresApplier:
		a.checkpointGuard = &guard
	case *DamengApplier:
		a.checkpointGuard = &guard
	}
	return a.Apply(ctx, changes, next)
}

func InitializeTargetBootstrapRecord(ctx context.Context, cfg Config, record BootstrapRecord) error {
	applier, err := newExistingTargetApplier(ctx, cfg)
	if err != nil {
		return err
	}
	defer applier.Close()
	return initializeTargetCheckpoint(ctx, applier, record)
}

func initializeTargetCheckpoint(ctx context.Context, a targetApplier, record BootstrapRecord) error {
	s := checkpointStoreFor(a)
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if err = s.requireOwner(ctx, tx, true); err != nil {
		return err
	}
	switch a := a.(type) {
	case *PostgresApplier:
		err = a.writeBootstrapRecord(ctx, tx, record, true)
	case *DamengApplier:
		err = a.insertBootstrapRecord(ctx, tx, record)
	}
	if err != nil {
		return err
	}
	return tx.Commit()
}
